  for (i = 0; i < 18; i++) s += "<circle cx='" + (r() * w).toFixed(0) + "' cy='" + (r() * h * .65).toFixed(0) + "' r='" + (r() * 1.5 + .3).toFixed(1) + "' fill='#fff' opacity='" + (r() * .25 + .05).toFixed(2) + "'/>";
  var m = Math.min(w, h), cx = w * (.45 + r() * .3), hz = h * .62;
